from pathlib import Path
import json,gzip,hashlib,re,datetime,subprocess
out=Path('00_nucleo/diagnosticos/clippy-aridade-interna-2026-10-16');prior=Path('00_nucleo/diagnosticos/clippy-excecoes-2026-10-16');sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
v=json.loads((prior/'validation-details.json').read_text());assert all(sha(p)==h for p,h in v['source_hashes'].items())
ids={'C047','C066','C102','C045','C062','C064'};classification=[x for x in json.loads(Path('00_nucleo/diagnosticos/too-many-arguments-2026-10-15/classification.json').read_text()) if x['id'] in ids];assert len(classification)==6
plans={
'03_infra/src/export/render.rs': 'C047: retirar apenas o parâmetro privado _text e seu argumento no dispatcher raster. Deixar de extrair text do padrão TextShaped somente nesse dispatcher, já que deixa de ser usado; o campo autoral de FrameItem permanece. Após confirmar a função com oito inputs reais, usar #[expect(clippy::too_many_arguments, reason="C047: Leaf raster usa oito inputs efetivos de pintura; texto autoral não é transportado para PNG")]. Corpo de pintura, face, upem.max(1), offsets, alpha, transformações e caminhos omitidos ficam idênticos.',
'03_infra/src/export/svg/glyphs.rs': 'C066: retirar somente _text do helper pub(super) de contornos, mantendo oito inputs e o corpo atual. Depois do cleanup, usar #[expect(clippy::too_many_arguments, reason="C066: Leaf SVG usa oito inputs efetivos de contorno, face, escala e definições; texto HTML segue writer separado")]. Não retirar texto do writer HTML, da entidade ou das APIs públicas; manter upem==0, fallback, glyph IDs, defs, escala e avanços.',
'03_infra/src/export/svg.rs': 'Migrar somente a chamada ao helper de contornos para não fornecer text. Preservar a extração text e a chamada render_html_text no ramo html_frame, que continua usando conteúdo autoral. Não alterar a assinatura pública ou o futuro contexto de sessão C071, que permanece pendente.',
'03_infra/src/pipeline/pdf.rs': 'C102: criar PdfCompileRequest estritamente privado, sem derive Default, contendo full_error, document_id, stream_mode, pdf_tagged_override, features, pretty_override, pages_override, standard_override e oracle nos mesmos tipos atuais. compile_to_pdf_bytes_impl recebe World, Source, request e &mut Timings; desestruturar request uma vez no início e conservar literalmente o restante do corpo. As três fachadas diretas montam os mesmos valores em campos nomeados, conservando oracle false/false/true, None/Some até resolução documental e ordem das expressões puras. Nenhuma fachada pública muda.',
'03_infra/src/export/gradients/mod.rs': 'C045: em scan_all_gradients, criar Collector local proprietário de ptr_to_idx, refs, grad_objs, next_id e counter. O walk recursivo recebe items, parent_bbox_override, page_height, placement e &mut Collector. Inicializar next_id=first_id e counter=1, manter incremento por Function/Shading/Pattern e a mesma ordem de background/body/foreground, Shape fill/stroke e células de tiling; mover as mesmas saídas ao retorno. Não alterar o segundo walk de pattern_resources_for_page, dedup keys, posição/conic domain, match exaustivo, IDs, geometria, ownership de Arc ou limites.',
'03_infra/src/export/stream.rs': 'C062/C064: substituir os construtores internos cidfont/multifont por with_font_scenario, recebendo os quatro recursos emprestados, FontScenario existente e StreamMode (seis argumentos). type1 conserva sua assinatura e delega com FontScenario::Type1. O novo construtor conserva todos os campos/defaults de PageContext: tiling_names None, tags Disabled, semantic_mcids vazio, ua1/oracle false, modo recebido. Não alterar FontScenario/visibilidade/variants ou criar validação de cardinalidade/clone de tabelas. Atualizar a fixture CIDFont do teste de stream para construir o mesmo cenário, mantendo seus asserts e bytes esperados.',
'03_infra/src/export/builder/fonts.rs': 'Migrar as duas composições de PageContext para with_font_scenario e FontScenario::{Cidfont,Multifont} nomeados com exatamente os mesmos empréstimos e índices. CIDFont conserva bitmap Some/None por bitmap_only; Multifont conserva bindings Some(LookupCache::default()) criado uma vez por contexto. Manter setters with_pdf_tags e with_oracle, tiling_names, ordem de emissão, subsetting e demais algoritmos intactos. Importar FontScenario somente do módulo interno stream, sem reexport público novo.'
}
files={};owners={}
for source in plans:
 owner=re.search(r'^//! @prompt (.+)$',Path(source).read_text(),re.M).group(1);owners[source]=owner
 for p in [source,owner]:files[p]=dict(text=Path(p).read_text(),sha256=sha(p))
inventory=json.loads((prior/'clippy-inventory.json').read_text());cases=[]
for c in classification:
 matches=[]
 for i in inventory:
  if i['code']!='clippy::too_many_arguments' or i['spans'][0]['file_name']!=c['path']:continue
  s=i['spans'][0];fragment=Path(c['path']).read_bytes()[s['byte_start']:s['byte_end']].decode()
  if re.search(r'\bfn '+c['function']+r'\b',fragment):matches.append(i)
 assert len(matches)==1,c['id'];x=matches[0];cases.append(dict(id=c['id'],rule=x['code'],source=c['path'],line=x['spans'][0]['line_start'],function=c['function'],prescription=c['prescription'],span=x['spans'][0]))
all_hashes={str(p):sha(p) for top in ['01_core','02_shell','03_infra','04_wiring','benches','00_nucleo/prompts'] for p in Path(top).rglob('*') if p.is_file() and p.suffix in ['.rs','.md','.toml']}
before=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),status=subprocess.check_output(['git','status','--porcelain=v1'],text=True),diffstat=subprocess.check_output(['git','diff','HEAD','--stat'],text=True),files=files,all_source_hashes=all_hashes,cases=cases,owners=owners,plans=plans)
assert not (out/'before.json.gz').exists()
with gzip.open(out/'before.json.gz','wt') as f:json.dump(before,f)
for name in ['run.py','seal.py','seal_owned.py','monitor.py']:
 s=(prior/'workers'/name).read_text().replace('clippy-excecoes-2026-10-16','clippy-aridade-interna-2026-10-16').replace('TEKT_EXCECOES_MEMORY_LIMIT','TEKT_ARIDADE_MEMORY_LIMIT');(out/'workers'/name).write_text(s)
for source,owner in owners.items():
 text='\n\n## Aridade interna — materialização de seis casos, 2026-10-16\n\n### Medição anterior à decisão\n\nAs fontes, chamadores, cláusulas vigentes, spans e inventário de 28 avisos foram conferidos antes da decisão. `00_nucleo/diagnosticos/clippy-aridade-interna-2026-10-16/before.json.gz` guarda fontes/L0 completos, hashes, HEAD, working tree não commitado, UTC e git diff HEAD --stat. A auditoria anterior classifica estes casos como correção; não são exceções diretas. O RED deve observar as aridades atuais antes de alterações; controles funcionais existentes serão corridos antes/depois. É refatoração de representação privada, sem nova paridade ou ganho de performance medido.\n\n### Responsabilidade exclusiva e aceitação\n\n'+plans[source]+'\n\nFluxo contínuo ADR-0127: nenhuma API externamente pública, default do produto, fase, dependência ou semântica é alterada. Tipos/constructors novos ficam internos; contratos públicos existentes permanecem. Este adendo concretiza somente os seis casos nominais; substitui proibições genéricas de supressão apenas para as duas expectativas residuais condicionadas C047/C066 após remover _text. As outras cinco aridades a corrigir continuam visíveis. Não elevar limiar ou silenciar no módulo/impl/crate. L0 precede código e resselo restrito. Confirmar preservação das assinaturas externamente públicas, campos/valores transportados, controles PNG/SVG/PDF, precedência/diagnósticos/recursos/MCIDs e ausência de mutações globais. Usar os testes existentes sem relaxar fixtures/esperados; não escrever testes que espelhem os carriers privados. Revalidar suíte workspace completa, build, Clippy all-targets e unfulfilled_lint_expectations, Rustdoc, fmt e linhagem estrita/reversa, mantendo 12 GiB, swap zero e um job.\n'
 Path(owner).write_text(Path(owner).read_text()+text)
(out/'l0-before-code.json').write_text(json.dumps(dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),owners={p:sha(p) for p in owners.values()},sources_still_original=all(sha(p)==files[p]['sha256'] for p in owners)),indent=2)+'\n')
print(json.dumps(dict(cases=len(cases),consumers=len(owners))))
